const s=ctx.state,gl=ctx.gl;
s.program=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,"#version 300 es
precision highp float;
#define GLSLIFY 1
in vec2 v_uv;out vec4 outColor;uniform vec2 u_resolution;uniform sampler2D u_image;
uniform int u_shape;
uniform float u_turn;
float sdTorus( vec3 p, vec2 t )
{
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}

float sdSphere( vec3 p, float s )
{
  return length( p ) - s;
}

float sdBox( vec3 p, vec3 b )
{
  vec3 d = abs(p) - b;
  return min(max(d.x,max(d.y,d.z)),0.0) +
         length(max(d,0.0));
}

float field(vec3 q){q.xz=mat2(cos(u_turn),-sin(u_turn),sin(u_turn),cos(u_turn))*q.xz;q.yz=mat2(.8,-.6,.6,.8)*q.yz;if(u_shape==1)return sdSphere(q,.7);if(u_shape==2)return sdBox(q,vec3(.5));return sdTorus(q,vec2(.55,.2));}
void main(){vec2 uv=v_uv,p=(uv*2.-1.)*u_resolution/min(u_resolution.x,u_resolution.y);vec3 color;vec3 ro=vec3(0,0,2.6),rd=normalize(vec3(p,-2.));float t=0.;bool hit=false;for(int i=0;i<100;i++){float d=field(ro+rd*t);if(d<.001){hit=true;break;}t+=d;if(t>6.)break;}color=vec3(.035,.075,.13);if(hit){vec3 q=ro+rd*t,e=vec3(.002,0,0),n=normalize(vec3(field(q+e.xyy)-field(q-e.xyy),field(q+e.yxy)-field(q-e.yxy),field(q+e.yyx)-field(q-e.yyx)));color=vec3(.29,.84,.74)*(.18+.82*max(dot(n,normalize(vec3(-1,2,3))),0.));}
outColor=vec4(color,1);}");
